ROOT = pathlib.Path(__file__).resolve().parents[1]
REPO = ROOT / "zoo"
PINS = {'zoo_keeper/core/doors.py': '8c8e9c17bafa2947', 'zoo_keeper/recipes/_arch.py': '0fca5938ac3e1a49'}
EDITS = {'zoo_keeper/core/doors.py': [('lines 41-41', '    return "M_Door_%s" % finish, (tint if tint is not None else default_color), kind\n', '    return "M_Door_%s" % finish, (tint if tint is not None else default_color), kind\n\n\n#: A DOOR HAS HARDWARE (1.124.0). The walker, walking cold run 9386, at a\n#: rowhome\'s stoop: "many of the rowhome doors dont have doorknobs?" -- the\n#: leaf was one flat box in its paint. A painted panel door: two raised panels\n#: on its street face, in the leaf\'s own material (they merge with it, no draw),\n#: and a knob on an escutcheon plate at the latch edge at handle height, in one\n#: shared brass (`HARDWARE`: one material for every door in a build, so the\n#: Empties\' per-side merge carries it as one more mesh a front at most). Each\n#: piece sinks `SINK` into the leaf, so no face of it lies on the leaf\'s face\n#: (`tests/test_coincident_faces.py`\'s rule). Sizes: a residential knob about\n#: 2 1/4 in across on its rose, 2 3/8 in back from the latch edge, about 38 in\n#: to its centre; the plate rounded to what reads at play distance. Built by\n#: `recipes/_arch.py`.\nKNOB_D = 0.06\nKNOB_PROUD = 0.06\nKNOB_Z = 0.95\nKNOB_FROM_EDGE = 0.07\nPLATE = (0.065, 0.012, 0.20)\nPANEL_INSET = 0.11\nPANEL_PROUD = 0.012\nPANEL_GAP = 0.12\nSINK = 0.001\nHARDWARE = ("M_Door_hardware_brass", (0.71, 0.55, 0.24), "metal_painted")\n')], 'zoo_keeper/recipes/_arch.py': [('lines 294-296', '        materials.assign([leaf], materials.make_material(name, colour, kind))\n        objs.append(leaf)\n\n', '        leaf_mat = materials.make_material(name, colour, kind)\n        materials.assign([leaf], leaf_mat)\n        objs.append(leaf)\n        # ITS PANELS AND ITS KNOB (1.124.0, `doors`\' A DOOR HAS HARDWARE): on the\n        # street face, +Y, each sunk doors.SINK into the leaf\n        face_y = d / 2.0 - FACADE_DOOR_SETBACK\n        cx = (void["x0"] + void["x1"]) / 2.0\n        bm = geometry.new_bm()\n        pw = lw - 2.0 * doors.PANEL_INSET\n        ph = (lh - 2.0 * doors.PANEL_INSET - doors.PANEL_GAP) / 2.0\n        if pw > 0.1 and ph > 0.1:\n            for k in (0, 1):\n                pz = void["z0"] + doors.PANEL_INSET + ph / 2.0 + k * (ph + doors.PANEL_GAP)\n                geometry.add_box(bm, (cx, face_y + (doors.PANEL_PROUD - doors.SINK) / 2.0, pz),\n                                 (pw, doors.PANEL_PROUD + doors.SINK, ph))\n            panels = geometry.bm_to_object(bm, f"{root}_LeafPanels", collection, bevel=0.0,\n                                           texel=1.0, rng=rng, wear=wear)\n            materials.assign([panels], leaf_mat)\n            objs.append(panels)\n        kx = void["x1"] - doors.KNOB_FROM_EDGE\n        kz = void["z0"] + doors.KNOB_Z\n        bm = geometry.new_bm()\n        geometry.add_box(bm, (kx, face_y + (doors.PLATE[1] - doors.SINK) / 2.0, kz),\n                         (doors.PLATE[0], doors.PLATE[1] + doors.SINK, doors.PLATE[2]))\n        geometry.add_cylinder(bm, (kx, face_y + doors.PLATE[1] + doors.KNOB_PROUD / 2.0 - doors.SINK, kz),\n                              doors.KNOB_D / 2.0, doors.KNOB_PROUD, segments=8, axis="Y")\n        knob = geometry.bm_to_object(bm, f"{root}_LeafHardware", collection, bevel=0.0,\n                                     texel=1.0, rng=rng, wear=wear * 0.5)\n        materials.assign([knob], materials.make_material(*doors.HARDWARE))\n        objs.append(knob)\n\n')]}
NEW_FILES = {'tests/test_door_hardware.py': '"""An Empty\'s shut front door has panels and a knob (1.124.0). The walker, walking cold run 9386: "many of the\nrowhome doors dont have doorknobs?" -- the leaf was one flat box.\n\nThe pure half holds the sizes; the bpy half builds a facade doorway and finds the hardware where a hand would reach\nit. It skips without Blender and was run inside Blender 5.1.1 for this change, from the repo root:\n\n    blender -b --factory-startup --python-expr "import sys, pytest; sys.path.insert(0, \'.\'); print(\'rc\', int(pytest.main([\'-q\', \'-p\', \'no:cacheprovider\', \'tests/test_door_hardware.py\'])))"\n"""\nfrom __future__ import annotations\n\nimport pytest\n\nfrom zoo_keeper.core import doors as A\n\n\ndef test_the_knob_is_where_a_hand_reaches_it():\n    assert 0.85 <= A.KNOB_Z <= 1.05\n    assert 0.05 <= A.KNOB_FROM_EDGE <= 0.09\n    assert A.SINK > 0.0 and A.PANEL_PROUD > A.SINK\n    name, colour, kind = A.HARDWARE\n    assert name.startswith("M_Door_hardware") and kind == "metal_painted"\n\n\n@pytest.mark.parametrize("finish", [None, "navy", "stained"])\ndef test_bpy_a_facade_door_has_panels_and_a_knob(finish, tmp_path):\n    pytest.importorskip("bpy")\n    import bpy\n    from zoo_keeper.core import kit\n    from zoo_keeper.bpylayer import build as B\n    for o in list(bpy.data.objects):\n        bpy.data.objects.remove(o, do_unlink=True)\n    slot = {"slot_id": "d", "role": "doorway", "size_mod": "full", "style": 1, "material": "brick",\n            "glazing": "facade",\n            "fit": {"dims": [2.0, 0.3, 3.3], "pivot": "center",\n                    "openings": [{"kind": "door", "width": 1.0, "height": 2.2, "sill": 0.0}],\n                    "collision": "convex"}}\n    if finish:\n        slot["door"] = finish\n    plan = kit.plan_kit({"building_id": "t", "slots": [slot]}, theme="delco_1997", style=1)\n    B.build_module(plan["modules"][0], str(tmp_path / "out"), theme="delco_1997", style=1,\n                   options={"save_blend": False})\n    names = [o.name for o in bpy.data.objects if o.type == "MESH"]\n    hw = [o for o in bpy.data.objects if o.type == "MESH" and o.name.endswith("_LeafHardware")]\n    panels = [o for o in bpy.data.objects if o.type == "MESH" and o.name.endswith("_LeafPanels")]\n    assert hw and panels, names\n    assert hw[0].data.materials[0].name == A.HARDWARE[0]\n'}
CHANGELOG = '## [1.124.0] - an Empty\'s front door has panels and a knob\n\n**The walker, walking cold run 9386** (the factory\'s `docs/findings/walk_2026-10-23_9386/`, finding 13), at\ngs_empty_rowhome_j\'s stoop: "many of the rowhome doors dont have doorknobs?" -- an Empty\'s shut front door was one flat\nbox in its house\'s paint (`_arch.py`, 1.61.0; its finish 1.72.0), no panels, no hardware.\n\n### Changed\n- **A painted panel door** (`recipes/_arch.py`, sizes in `core/doors.py`): two raised panels on its street face in the\n  leaf\'s own material, which merge with it and cost no draw; a knob on an escutcheon plate at the latch edge,\n  0.95 m to its centre and 0.07 m in from the edge, in one shared brass (`doors.HARDWARE`, `M_Door_hardware_brass`) --\n  one material for every door in a build, so Level Factory\'s per-side merge of an Empty carries it as one more mesh\n  a front at most. Each piece is sunk 1 mm into the leaf, so no face of it lies on the leaf\'s face; the coincident-face\n  census passes unchanged (78 passed, the same xfail, Blender 5.1.1).\n\n### Tests\n- `tests/test_door_hardware.py` (new): the knob where a hand reaches it; in Blender, a facade doorway in no finish,\n  navy and stained builds its `_LeafPanels` and its `_LeafHardware` in the brass. The Blender test fails on 1.123.0.\n\n'
OLD_VERSION, NEW_VERSION = '1.123.0', '1.124.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: zoo/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: zoo/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: zoo/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: zoo/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Zoo %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in zoo/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
